/* All clubs, players and events are fictional. Event IDs are stable evidence references. */
const $=id=>document.getElementById(id);
const {events,moments,windowStats}=MatchData;
let selected=1,minute=0,timer=null;
const titles=['Eastport find their opening','Northbridge turn up the pressure','Eastport attack again'];
function explanation(m,analyst=false){if(analyst)return `${m.team}: pressure index ${m.before.pressure} → ${m.after.pressure} (+${m.delta}), comparing [${m.start-5}′, ${m.start}′) with [${m.start}′, ${m.end}′). Shots: ${m.before.shots} → ${m.after.shots}; successful box entries: ${m.before.entries} → ${m.after.entries}. This is a rule-based change signal, not a causal estimate or calibrated prediction.`;return `${m.team} created ${m.after.shots} shots and ${m.after.entries} successful penalty-area entries between minutes ${m.start} and ${m.end}, compared with ${m.before.shots} shots and ${m.before.entries} entries in the previous five minutes. That is a clear increase in attacking activity. It does not prove why the change happened or that a goal will follow.`;}
function renderMoments(){$('moments').innerHTML=moments.map((m,i)=>`<button class="moment ${i===selected?'selected':''}" data-index="${i}"><div class="moment-top"><span>0${i+1} / PRESSURE SHIFT</span><b>${m.start}′–${m.end}′</b></div><h4>${titles[i]}</h4><p>${m.after.shots} shots · ${m.after.entries} box entries · +${m.delta} pressure</p></button>`).join('');document.querySelectorAll('.moment').forEach(b=>b.onclick=()=>selectMoment(Number(b.dataset.index)));}
function renderDetail(){const m=moments[selected];$('detail-title').textContent=titles[selected];$('detail').innerHTML=`<div class="metric-row"><div class="metric"><strong>${m.before.pressure} → ${m.after.pressure}</strong>Attacking pressure</div><div class="metric"><strong>${m.after.shots}</strong>Shots in five minutes</div><div class="metric"><strong>${m.after.entries}</strong>Successful box entries</div></div><p>${explanation(m,$('audience').value==='analyst')}</p><div class="evidence-list">${m.after.evidence.map(e=>`<button data-event="${e.id}">${e.minute.toFixed(1)}′ · ${e.type==='shot'?'Shot':'Box entry'} ↗</button>`).join('')}</div><div id="evidence-event" class="evidence-event">Select an event to inspect its source and replay its position.</div>`;document.querySelectorAll('[data-event]').forEach(b=>b.onclick=()=>{const e=events.find(x=>x.id===b.dataset.event);pause();minute=e.minute;renderReplay(e);$('evidence-event').textContent=`${e.id} · ${e.team} · ${e.type.replace('_',' ')} · minute ${e.minute.toFixed(1)} · (${e.x}, ${e.y}) → (${e.endX}, ${e.endY}). Source: bundled synthetic fixture. Position units: 0–100, normalized toward the attacking goal.`;});}
function selectMoment(i){selected=i;pause();minute=moments[i].end;renderMoments();renderDetail();renderReplay();renderAI();}
function drawPlayers(){const positions=[[8,50],[24,20],[24,40],[24,65],[24,83],[43,25],[43,50],[43,75],[64,20],[68,50],[64,80]];let markup='';for(const [team,color]of [['Northbridge','#63b2f4'],['Eastport','#f59082']])positions.forEach(([x,y],i)=>{if(team==='Eastport')x=100-x;markup+=`<circle cx="${40+x*7.2}" cy="${40+y*3.8}" r="10" fill="${color}" stroke="#102017" stroke-width="2"/><text x="${40+x*7.2}" y="${44+y*3.8}" fill="#102017" text-anchor="middle" font-size="9" font-family="sans-serif" font-weight="bold">${i+1}</text>`;});$('players').innerHTML=markup;}
function renderReplay(explicit){$('seek').value=minute;$('minute').textContent=`${Math.floor(minute)}′ / 90′`;const goals=events.filter(e=>e.type==='goal'&&e.minute<=minute);$('score').innerHTML=`${goals.filter(e=>e.team==='Northbridge').length} <span>:</span> ${goals.filter(e=>e.team==='Eastport').length}`;$('clock').textContent=`${String(Math.floor(minute)).padStart(2,'0')}:${String(Math.floor(minute%1*60)).padStart(2,'0')} · ${minute>=90?'FULL TIME':minute>=45?'SECOND HALF':'FIRST HALF'}`;const e=explicit||events.filter(e=>e.minute<=minute).at(-1);$('event-label').textContent=e?`${e.team} · ${e.type.replace('_',' ')} · ${Math.floor(e.minute)}′`:'Ready for kick-off';if(e){const flip=x=>e.team==='Eastport'?100-x:x;const x1=40+flip(e.x)*7.2,y1=40+e.y*3.8,x2=40+flip(e.endX)*7.2,y2=40+e.endY*3.8;$('ball-path').setAttribute('d',`M${x1} ${y1}L${x2} ${y2}`);$('ball').setAttribute('cx',x2);$('ball').setAttribute('cy',y2);}else{$('ball-path').setAttribute('d','');$('ball').setAttribute('cx',400);$('ball').setAttribute('cy',230);}drawChart();}
function drawChart(){let html='<path d="M0 75H700" stroke="#344251"/>';for(let i=0;i<18;i++){for(const [team,color,dir]of [['Northbridge','#63b2f4',-1],['Eastport','#f59082',1]]){const stat=windowStats(team,i*5+1,i*5+6),h=stat.pressure*3;html+=`<rect x="${i*38.8+7}" y="${dir<0?75-h:75}" width="23" height="${Math.max(h,2)}" fill="${color}" opacity=".85" rx="2"><title>${team}, ${i*5+1}–${i*5+6} minutes: pressure ${stat.pressure}</title></rect>`;}}html+=`<path d="M${minute/90*700} 0V150" stroke="#d2f58b" stroke-width="2"/>`;$('chart').innerHTML=html;}
function pause(){clearInterval(timer);timer=null;$('play').textContent='▶ Play';$('play').setAttribute('aria-label','Play match');}
function play(){if(timer){pause();return;}if(minute>=90)minute=0;$('play').textContent='Ⅱ Pause';$('play').setAttribute('aria-label','Pause match');timer=setInterval(()=>{minute=Math.min(90,Math.floor(minute)+1);renderReplay();if(minute===90)pause();},Number($('speed').value));}
$('play').onclick=play;$('reset').onclick=()=>{pause();minute=0;renderReplay();};$('seek').oninput=e=>{pause();minute=Number(e.target.value);renderReplay();};$('speed').onchange=()=>{if(timer){pause();play();}};$('audience').onchange=()=>{renderDetail();renderAI();};
$('export').onclick=()=>{const report={project:'Turning Point',dataSource:'Entirely synthetic fictional match',method:'Five-minute windows; pressure = shots × 3 + successful box entries; change threshold >= 10; top three changes',limitations:['Heuristic signal, not causal inference','Schematic pitch; no tracking data','Model narrative may contain errors; review source events'],moments:moments.map((m,i)=>({...m,explanation:explanation(m),ai:aiResults.get(`${i}:simple`)||null,aiAnalyst:aiResults.get(`${i}:analyst`)||null})),events};const url=URL.createObjectURL(new Blob([JSON.stringify(report,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='turning-point-match-report.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
drawPlayers();renderMoments();renderDetail();renderReplay();
